{
  "file_path": "/workspace/build/coding_tasks.py",
  "content": """"35 coding tasks: id, spec prompt, reference solution (str), tests (list of arg-tuples).

The build script executes each reference solution to compute expected outputs,
guaranteeing test-oracle consistency. Candidate must define `solve` (or a class).
"""

TASKS = []

def T(tid, spec, ref, tests, ref_setup=None):
    TASKS.append(dict(id=tid, spec=spec, ref=ref, tests=tests, ref_setup=ref_setup))

# ---------------- Easy ----------------

T("c01", """Return the k most frequent words in the given text. Words are case-insensitive, split on whitespace,
stripped of surrounding punctuation (.,!?;:"'()). Ties are broken by alphabetical order. Return a list of the words
in that order (length k, pad with "" if fewer distinct words exist).""",
"""
def solve(text, k):
    import re
    words = [w.strip('.,!?;:\\\"\\'()').lower() for w in text.split()]
    words = [w for w in words if w]
    from collections import Counter
    c = Counter(words)
    items = sorted(c.items(), key=lambda x: (-x[1], x[0]))
    res = [w for w, _ in items[:k]]
    while len(res) < k:
        res.append("")
    return res
""",
[("the quick brown fox jumps over the lazy dog the fox", 3),
 ("a a a b b c", 2),
 ("Hello, hello! World.", 2),
 ("", 3)])

T("c02", """Convert a Roman numeral string (I, V, X, L, C, D, M; length 1..15) to its integer value.
Assume the input is a valid roman numeral.""",
"""
def solve(s):
    vals = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    total = 0
    for i, ch in enumerate(s):
        v = vals[ch]
        if i + 1 < len(s) and vals[s[i+1]] > v:
            total -= v
        else:
            total += v
    return total
""",
[("III",), ("MCMXCIV",), ("LVIII",), ("IX",)])

T("c03", """Given a list that may contain integers or nested lists, return a flat list of all integers,
flattening only up to depth `maxdepth` (nesting deeper than maxdepth stays as a nested list in the output).""",
"""
def solve(lst, maxdepth):
    if maxdepth <= 0:
        return [x for x in lst]
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(solve(x, maxdepth - 1))
        else:
            out.append(x)
    return out
""",
[([1,[2,[3,[4]]]], 1), ([1,[2,[3,[4]]]], 2), ([1,[2,[3,[4]]]], 9), ([], 3)])

T("c04", """Run-length encode a lowercase string: return a list of (character, count) pairs for each maximal run.
Order preserved.""",
"""
def solve(s):
    out = []
    for ch in s:
        if out and out[-1][0] == ch:
            out[-1][1] += 1
        else:
            out.append([ch, 1])
    return [tuple(p) for p in out]
""",
[("aaabbbcc",), ("a",), ("",), ("ababab",)])

T("c05", """Given two date strings 'YYYY-MM-DD', return the number of days between them (absolute value).""",
"""
def solve(d1, d2):
    from datetime import date
    a = date(*map(int, d1.split('-')))
    b = date(*map(int, d2.split('-')))
    return abs((a - b).days)
""",
[("2024-01-01","2024-03-01",), ("2020-02-28","2020-03-01",), ("2023-12-31","2024-01-01",)])

T("c06", """Transpose a rectangular matrix (list of lists) and return the result.""",
"""
def solve(m):
    if not m:
        return []
    return [[m[i][j] for i in range(len(m))] for j in range(len(m[0]))]
""",
[([[1,2,3],[4,5,6]],), ([[1],[2]],), ([[7]],)])

T("c07", """Given a string of letters, return the alphabetically sorted string of letters missing to make it a pangram
(each letter a-z at least once). If already a pangram, return ''. Case-insensitive input.""",
"""
def solve(s):
    have = set(s.lower())
    missing = [chr(c) for c in range(ord('a'), ord('z')+1) if chr(c) not in have]
    return ''.join(missing)
""",
[("The quick brown fox jumps over the lazy dog",), ("hello",), ("abc",)])

T("c08", """Given rows of comma-separated values (header row first) and a column name, return the sum of numeric values in
that column (values that are not parseable as numbers are ignored). Return the sum rounded to 2 decimals.""",
"""
def solve(csv_text, col):
    lines = [l for l in csv_text.strip().split('\\n') if l]
    header = [h.strip() for h in lines[0].split(',')]
    idx = header.index(col)
    total = 0.0
    for line in lines[1:]:
        parts = [p.strip() for p in line.split(',')]
        try:
            total += float(parts[idx])
        except ValueError:
            pass
    return round(total, 2)
""",
[("name,amount\\nalice,10.5\\nbob,3\\ncarol,x", "amount"), ("a,b\\n1,2\\n3,4", "b")])

# ---------------- Medium ----------------

T("c09", """Evaluate a Reverse Polish Notation expression given as a list of tokens (numbers as strings, or one of
+ - * /). Division is float division. Return the final value as a float. Raise/handle nothing: input is valid.""",
"""
def solve(tokens):
    st = []
    for t in tokens:
        if t in '+-*/':
            b = st.pop(); a = st.pop()
            if t == '+': st.append(a + b)
            elif t == '-': st.append(a - b)
            elif t == '*': st.append(a * b)
            else: st.append(a / b)
        else:
            st.append(float(t))
    return st[0]
""",
[(["2","1","+","3","*"],), (["4","13","5","/","+"],), (["10","2","-","8","*","0.5","+"],)])

T("c10", """Check whether brackets in a string are balanced. Bracket types: () [] {}. Non-bracket characters may appear.
Return True/False.""",
"""
def solve(s):
    pairs = {')':'(', ']':'[', '}':'{'}
    st = []
    for ch in s:
        if ch in '([{':
            st.append(ch)
        elif ch in ')]}':
            if not st or st[-1] != pairs[ch]:
                return False
            st.pop()
    return not st
""",
[("a(b[c]d)e",), ("([)]",), ("",), ("(((",), (")(",)])

T("c11", """Given a list of closed intervals [start, end) with integer endpoints, merge overlapping intervals and return
the total length covered by their union as an integer.""",
"""
def solve(intervals):
    if not intervals:
        return 0
    ivs = sorted(intervals)
    total = 0
    cs, ce = ivs[0]
    for s, e in ivs[1:]:
        if s <= ce:
            ce = max(ce, e)
        else:
            total += ce - cs
            cs, ce = s, e
    total += ce - cs
    return total
""",
[([[0,2],[2,4],[5,7]],), ([[0,10],[3,4]],), ([[1,3],[5,6],[8,10]],), ([],)])

T("c12", """Implement an LRU cache class named `LRUCache` with __init__(self, capacity), get(self, key) -> value or -1,
and put(self, key, value). Both get and put count as uses. Keys and values are ints. get returns -1 on miss.
solve(capacity) must return an instance of this class.""",
"""
def solve(capacity):
    class LRUCache:
        def __init__(self, capacity):
            self.cap = capacity
            self.od = {}
        def get(self, key):
            if key in self.od:
                v = self.od.pop(key)
                self.od[key] = v
                return v
            return -1
        def put(self, key, value):
            if key in self.od:
                self.od.pop(key)
            self.od[key] = value
            if len(self.od) > self.cap:
                self.od.pop(next(iter(self.od)))
    return LRUCache(capacity)
""",
[(2,), (1,), (3,)])

T("c13", """Dijkstra: given a graph as dict {node: list of (neighbor, nonneg_weight)} and source and target nodes,
return the shortest path distance as a number, or -1 if unreachable.""",
"""
def solve(graph, src, dst):
    import heapq
    dist = {src: 0}
    pq = [(0, src)]
    while pq:
        d, u = heapq.heappop(pq)
        if u == dst:
            return d
        if d > dist.get(u, float('inf')):
            continue
        for v, w in graph.get(u, []):
            nd = d + w
            if nd < dist.get(v, float('inf')):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return -1 if dst not in dist else dist[dst]
""",
[({'a':[('b',1),('c',4)],'b':[('c',2),('d',5)],'c':[('d',1)],'d':[]},'a','d'),
 ({'a':[('b',1)],'b':[],'c':[]},'a','c')])

T("c14", """Return the length of the longest strictly increasing subsequence of a list of integers.""",
"""
def solve(nums):
    import bisect
    tails = []
    for x in nums:
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)
""",
[([10,9,2,5,3,7,101,18],), ([0,1,2,3],), ([5,4,3,2,1],), ([],)])

T("c15", """Group a list of words into anagram groups. Return a sorted list of groups, each group a sorted list of
words, groups sorted by their first element.""",
"""
def solve(words):
    from collections import defaultdict
    g = defaultdict(list)
    for w in words:
        g[''.join(sorted(w))].append(w)
    res = sorted(sorted(v) for v in g.values())
    return res
""",
[(["eat","tea","tan","ate","nat","bat"],), ([""],), (["a"],)])

T("c16", """Given a list of meeting (start, end) pairs with integer times, return the maximum number of non-overlapping
meetings one can attend completely (a meeting [s,e) overlaps another if intervals intersect).""",
"""
def solve(meetings):
    ms = sorted(meetings, key=lambda x: x[1])
    count = 0
    last_end = float('-inf')
    for s, e in ms:
        if s >= last_end:
            count += 1
            last_end = e
    return count
""",
[([(1,3),(2,4),(3,5),(0,7),(5,8)],), ([(1,2),(2,3),(3,4)],), ([],)])

T("c17", """Evaluate a polynomial given as a coefficient list (index i = coefficient of x^i, lowest degree first)
at point x, and return the coefficient list of its derivative (empty list if degree 0). Return (value, deriv_coeffs)
as a tuple. deriv_coeffs must have no trailing zeros (or be empty).""",
"""
def solve(coeffs, x):
    val = 0
    for c in reversed(coeffs):
        val = val * x + c
    deriv = [i * coeffs[i] for i in range(1, len(coeffs))]
    while deriv and deriv[-1] == 0:
        deriv.pop()
    return (val, deriv)
""",
[([1,2,3], 2.0), ([5], 10), ([0,0,1], 3)])

T("c18", """Given a nested dict/list structure and a path string like 'a.b[0].c' (dots for dict keys, [i] for list
indices), return the value at that path, or None if the path does not resolve.""",
"""
def solve(obj, path):
    import re
    toks = re.findall(r'[^\\.\\[\\]]+|\\[\\d+\\]', path)
    cur = obj
    for t in toks:
        if t.startswith('['):
            idx = int(t[1:-1])
            if isinstance(cur, list) and idx < len(cur):
                cur = cur[idx]
            else:
                return None
        else:
            if isinstance(cur, dict) and t in cur:
                cur = cur[t]
            else:
                return None
    return cur
""",
[({'a':[{'b':1},{'c':2}],'d':{'e':3}}, 'a[1].c'), ({'a':[{'b':1},{'c':2}],'d':{'e':3}}, 'd.e'),
 ({'a':[{'b':1},{'c':2}],'d':{'e':3}}, 'a[5].z')])

T("c19", """Convert a snake_case identifier to camelCase. Words are separated by single underscores. The first word
stays lowercase; each following word is capitalized (first letter upper, rest lower). Digits are part of words.
Example: 'hello_world_test' -> 'helloWorldTest'.""",
"""
def solve(s):
    parts = s.split('_')
    return parts[0] + ''.join(p.capitalize() for p in parts[1:])
""",
[("hello_world",), ("already",), ("a_b_c_d",), ("x2_y_z",)])

T("c20", """Topological sort: given a DAG as {node: [prerequisites]} (edges point prerequisite -> dependent, i.e. the
listed nodes must come before the key... note: key depends on listed nodes), return a topological order as a list
where every listed node appears before the key that depends on it. If there is a cycle, return None. All nodes that
appear anywhere must be included; nodes not appearing as keys have no prerequisites. Deterministic order: among
available nodes, pick the alphabetically smallest.""",
"""
def solve(graph):
    import heapq
    nodes = set(graph)
    for deps in graph.values():
        nodes.update(deps)
    indeg = {n: 0 for n in nodes}
    dependents = {n: [] for n in nodes}
    for k, deps in graph.items():
        for d in deps:
            indeg[k] += 1
            dependents[d].append(k)
    avail = [n for n in nodes if indeg[n] == 0]
    heapq.heapify(avail)
    out = []
    while avail:
        n = heapq.heappop(avail)
        out.append(n)
        for m in dependents[n]:
            indeg[m] -= 1
            if indeg[m] == 0:
                heapq.heappush(avail, m)
    if len(out) != len(nodes):
        return None
    return out
""",
[({'b':['a'],'c':['b'],'d':['b','c']},), ({'a':['b'],'b':['a']},), ({},)])

T("c21", """Maximum sum of a non-empty contiguous subarray (Kadane), but the array is circular: the subarray may wrap
around the end to the beginning. Return the maximum sum as an integer.""",
"""
def solve(nums):
    if not nums:
        return 0
    def kadane(a):
        best = cur = a[0]
        for x in a[1:]:
            cur = max(x, cur + x)
            best = max(best, cur)
        return best
    total = sum(nums)
    # min subarray (non-full-wrap)
    def kadmin(a):
        best = cur = a[0]
        for x in a[1:]:
            cur = min(x, cur + x)
            best = min(best, cur)
        return best
    nonwrap = kadane(nums)
    if all(x < 0 for x in nums):
        return nonwrap
    return max(nonwrap, total - kadmin(nums))
""",
[([1,-2,3,-2],), ([5,-3,5],), ([3,-1,2,-1],), ([-2,-3,-1],)])

T("c22", """Given lo and hi (inclusive positive integers), count how many integers in [lo, hi] have a population count
(number of set bits) equal to k.""",
"""
def solve(lo, hi, k):
    count = 0
    for n in range(lo, hi + 1):
        if bin(n).count('1') == k:
            count += 1
    return count
""",
[(1, 16, 2), (1, 100, 3), (10, 10, 2)])

T("c23", """Given a list of coin denominations (positive ints, unlimited supply) and an amount, return the number of
distinct ordered ways? No: return the number of distinct unordered combinations of coins that sum to the amount.
Return 0 if impossible.""",
"""
def solve(coins, amount):
    dp = [0] * (amount + 1)
    dp[0] = 1
    for c in sorted(set(coins)):
        for a in range(c, amount + 1):
            dp[a] += dp[a - c]
    return dp[amount]
""",
[([1,2,3], 4), ([2], 3), ([5,10], 20)])

# ---------------- Hard ----------------

T("c24", """Edit distance with custom operation costs given as a dict with keys 'insert', 'delete', 'replace' (positive
ints). Return the minimum total cost to transform string a into string b.""",
"""
def solve(a, b, costs):
    import functools
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i * costs['delete']
    for j in range(n + 1):
        dp[0][j] = j * costs['insert']
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j] + costs['delete'],
                               dp[i][j-1] + costs['insert'],
                               dp[i-1][j-1] + costs['replace'])
    return dp[m][n]
""",
[("kitten","sitting",{'insert':1,'delete':1,'replace':2}),
 ("abc","yabd",{'insert':2,'delete':3,'replace':1}),
 ("","xyz",{'insert':1,'delete':1,'replace':1})])

T("c25", """Return the number of distinct solutions to the n-queens puzzle on an n x n board for the given n.""",
"""
def solve(n):
    def backtrack(row, cols, d1, d2):
        if row == n:
            return 1
        total = 0
        for c in range(n):
            if c in cols or (row - c) in d1 or (row + c) in d2:
                continue
            total += backtrack(row + 1, cols | {c}, d1 | {row - c}, d2 | {row + c})
        return total
    return backtrack(0, set(), set(), set())
""",
[(8,), (4,), (1,), (6,)])

T("c26", """Solve a 4x4 Sudoku: given a 4x4 grid (list of 4 lists of 4 ints, 0 for empty) using digits 1-4 with the
standard 2x2 box constraint, return the solved grid as a list of lists of ints. The puzzle has a unique solution.
If unsolvable, return None.""",
"""
def solve(grid):
    def ok(g, r, c, v):
        for j in range(4):
            if g[r][j] == v: return False
        for i in range(4):
            if g[i][c] == v: return False
        br, bc = 2 * (r // 2), 2 * (c // 2)
        for i in range(br, br + 2):
            for j in range(bc, bc + 2):
                if g[i][j] == v: return False
        return True
    g = [row[:] for row in grid]
    def solve_rec():
        for r in range(4):
            for c in range(4):
                if g[r][c] == 0:
                    for v in range(1, 5):
                        if ok(g, r, c, v):
                            g[r][c] = v
                            if solve_rec():
                                return True
                            g[r][c] = 0
                    return False
        return True
    if solve_rec():
        return g
    return None
""",
[([[1,0,0,4],[0,4,1,0],[4,0,2,0],[0,1,0,3]],),
 ([[0,0,0,0],[0,1,4,0],[0,4,1,0],[0,0,0,0]],)])

T("c27", """Convex hull: given a list of (x, y) integer points (no three collinear duplicates issue: at least 3 points,
not all collinear), return the vertices of the convex hull in counter-clockwise order, starting from the
lexicographically smallest point (smallest x, then y). Use the monotone chain algorithm. Exclude collinear points
on hull edges.""",
"""
def solve(points):
    pts = sorted(set(map(tuple, points)))
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])
    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]
""",
[([(0,0),(0,2),(2,0),(2,2),(1,1)],), ([(0,0),(1,1),(2,2),(3,3),(1,0)],)])

T("c28", """PageRank: given edges as list of (from, to) among node labels (strings), damping factor d and iterations n,
run the power iteration: PR initialized uniformly; each step, rank flows along each out-edge equally; dangling nodes
distribute their rank uniformly to all nodes; newrank = (1-d)/N + d * (flow). Return the dict {node: rank} after n
iterations, ranks as floats. Node set = all nodes appearing in edges.""",
"""
def solve(edges, d, n):
    nodes = set()
    for a, b in edges:
        nodes.add(a); nodes.add(b)
    N = len(nodes)
    out = {u: [] for u in nodes}
    for a, b in edges:
        out[a].append(b)
    rank = {u: 1.0 / N for u in nodes}
    for _ in range(n):
        new = {u: (1 - d) / N for u in nodes}
        for u in nodes:
            if out[u]:
                share = rank[u] / len(out[u])
                for v in out[u]:
                    new[v] += d * share
            else:
                share = rank[u] / N
                for v in nodes:
                    new[v] += d * share
        rank = new
    return rank
""",
