T("c31", """Implement a class `Frac` for exact rational arithmetic: __init__(self, num, den) normalizes with
den>0 and gcd reduction; support +, *, == (with other Frac), and a method `text()` returning 'p/q' or 'p' when q==1.
solve() returns the class itself.""",
"""
def solve():
    from math import gcd
    class Frac:
        def __init__(self, num, den=1):
            if den == 0:
                raise ValueError
            g = gcd(abs(num), abs(den))
            num //= g; den //= g
            if den < 0:
                num, den = -num, -den
            self.num = num; self.den = den
        def __add__(self, other):
            return Frac(self.num * other.den + other.num * self.den, self.den * other.den)
        def __mul__(self, other):
            return Frac(self.num * other.num, self.den * other.den)
        def __eq__(self, other):
            return self.num == other.num and self.den == other.den
        def text(self):
            if self.den == 1:
                return str(self.num)
            return f"{self.num}/{self.den}"
    return Frac
""",
[(), ()])

T("c32", """Shortest edit script: transform string a into string b using only insertions and deletions (no
substitution). Return the minimum number of operations as an integer (this equals len(a)+len(b)-2*LCS(a,b)).""",
"""
def solve(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    lcs = dp[m][n]
    return m + n - 2 * lcs
""",
