T("c33", """Weighted interval scheduling: given a list of (start, end, profit) jobs with integer times, return the
maximum total profit of a non-overlapping subset (jobs [s,e) overlap if intervals intersect).""",
"""
def solve(jobs):
    import bisect
    jobs = sorted(jobs, key=lambda j: j[1])
    n = len(jobs)
    ends = [j[1] for j in jobs]
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        s, e, p = jobs[i-1]
        j = bisect.bisect_right(ends, s, 0, i - 1)
        dp[i] = max(dp[i-1], dp[j] + p)
    return dp[n]
""",
