T("c34", """Mini spreadsheet: given a dict mapping cell names like 'A1' to values (ints) or formulas (strings starting
with '='), evaluate formulas of the form '=EXPR' where EXPR is a sum of terms separated by + or -, and each term is
either an integer, a cell reference like B2, or a range function SUM(A1:B2) meaning the sum of the rectangle from
A1 to B2 inclusive (columns are single letters A..Z, rows are integers). Ranges expand row-major: e.g. A1:B2 covers
A1,B1,A2,B2. Formulas may reference cells whose values are also formulas; evaluate recursively. Return dict of all
cells (given ones included) mapped to their evaluated integer values. All references are valid; no cycles.""",
"""
def solve(cells):
    import re
    def expand(rng):
        m = re.match(r'^([A-Z])(\\d+):([A-Z])(\\d+)$', rng)
        c1, r1, c2, r2 = m.group(1), int(m.group(2)), m.group(3), int(m.group(4))
        out = []
        for r in range(r1, r2 + 1):
            for c in range(ord(c1), ord(c2) + 1):
                out.append(chr(c) + str(r))
        return out
    def term_val(t):
        t = t.strip()
        sm = re.match(r'^SUM\\(([A-Z]\\d+:[A-Z]\\d+)\\)$', t)
        if sm:
            return sum(cell_val(c) for c in expand(sm.group(1)))
        if re.match(r'^[A-Z]\\d+$', t):
            return cell_val(t)
        return int(t)
    memo = {}
    def cell_val(name):
        if name in memo:
            return memo[name]
        v = cells[name]
        if isinstance(v, str) and v.startswith('='):
            expr = v[1:]
            expr = expr.replace('-', '+-')
            total = sum(term_val(t) for t in expr.split('+') if t.strip())
        else:
            total = int(v)
        memo[name] = total
        return total
    return {name: cell_val(name) for name in cells}
""",
