T("c35", """KMP substring search: return a list of all starting indices where pattern p occurs in text t
(overlapping occurrences included). Return [] if none.""",
"""
def solve(t, p):
    if not p:
        return []
    kmp = [0] * len(p)
    k = 0
    for i in range(1, len(p)):
        while k and p[i] != p[k]:
            k = kmp[k-1]
        if p[i] == p[k]:
            k += 1
        kmp[i] = k
    out = []
    k = 0
    for i, ch in enumerate(t):
        while k and ch != p[k]:
            k = kmp[k-1]
        if ch == p[k]:
            k += 1
        if k == len(p):
            out.append(i - len(p) + 1)
            k = kmp[k-1]
    return out
""",
